    if rule_vol is None:
        return True
    if '-' in rule_vol:
        low, high = rule_vol.replace('k', '000').replace('m', '000000').split('-')
        return float(low) <= current_vol <= float(high)
    if '>' in rule_vol:
        val = float(rule_vol.replace('>', '').replace('k', '000').replace('m', '000000'))
        return current_vol > val
    if '<' in rule_vol:
        val = float(rule_vol.replace('<', '').replace('k', '000').replace('m', '000000'))
        return current_vol < val
    return False

def matches_fraud(rule_fraud, current_fraud):
    if rule_fraud is None:
        return True
    current_fraud_pct = current_fraud * 100
    if '-' in rule_fraud:
        low, high = rule_fraud.replace('%', '').split('-')
        return float(low) <= current_fraud_pct <= float(high)
    if '>' in rule_fraud:
        val = float(rule_fraud.replace('>', '').replace('%', ''))
        return current_fraud_pct > val
    if '<' in rule_fraud:
        val = float(rule_fraud.replace('<', '').replace('%', ''))
        return current_fraud_pct < val
    return False

