    if rule_delay == '<3' and current_delay in ['1', '2', 'immediate']:
        return True
    if rule_delay == '3-5' and current_delay in ['3', '4', '5']:
        return True
    if rule_delay == '>5' and current_delay in ['6', '7', 'manual']: # Assuming manual is >5
        return True
    return False

# Load transactions
transactions = []
