        if rule['account_type'] and account_type not in rule['account_type']:
            continue
        if not matches_capture_delay(rule['capture_delay'], capture_delay):
            continue
        if not matches_fraud(rule['monthly_fraud_level'], fraud_ratio):
            continue
        if not matches_volume(rule['monthly_volume'], total_volume):
            continue
        if rule['merchant_category_code'] and mcc not in rule['merchant_category_code']:
            continue
        if rule['is_credit'] is not None and rule['is_credit'] != tx['is_credit']:
            continue
        if rule['aci'] and tx['aci'] not in rule['aci']:
            continue
        is_domestic = tx['issuing_country'] == tx['acquirer_country']
        if rule['intracountry'] is not None:
            if rule['intracountry'] == 1.0 and not is_domestic:
                continue
            if rule['intracountry'] == 0.0 and is_domestic:
                continue
